nta.declaration:
// Game Constants
const int NUM_ENEMIES = 700;
const int TIMEOUT = 200;
const int LAST_SPAWN = 700;
typedef int[0, NUM_ENEMIES-1] enemy_id_t;
int damage_time = -1;

// Enemy Parameters
const int CIRCLE_SPEED = 1;
const int CIRCLE_HEALTH = 10;
const int CIRCLE_DAMAGE = 2;
const int SQUARE_SPEED = 3;
const int SQUARE_HEALTH = 20;
const int SQUARE_DAMAGE = 4;

// Turret Parameters
const int BASIC_RANGE = 2;
const int BASIC_FIRE_SPEED = 2;
const int BASIC_DAMAGE = 2;
const int CANNON_RANGE = 1;
const int CANNON_FIRE_SPEED = 7;
const int CANNON_DAMAGE = 5;
const int SNIPER_RANGE = 4;
const int SNIPER_FIRE_SPEED = 20;
const int SNIPER_DAMAGE = 8;

// Main Tower
const int MAIN_TOWER_HEALTH = 10;
int[0,TIMEOUT] enter_time[NUM_ENEMIES];

// Enemy tracking arrays
int pos[NUM_ENEMIES];
int hp[NUM_ENEMIES];
int dmg[NUM_ENEMIES];
int spawn_time[NUM_ENEMIES];
int time_on_map[NUM_ENEMIES];
int path_choice[NUM_ENEMIES];
int alt_pos[NUM_ENEMIES];
bool active[NUM_ENEMIES];
bool initialized=false;

void initialize_arrays() {
    int i;
    // Initialize the first 400 enemies as Circles
    for (i = 0; i < NUM_ENEMIES; i++) {
        active[i] = false;
    }
    for (i = 0; i < 400; i++) {
        pos[i] = 0;
        hp[i] = CIRCLE_HEALTH;
        dmg[i] = CIRCLE_DAMAGE;
        spawn_time[i] = i * 2; // Circles spawn every 2 time units
        time_on_map[i] = 0;
        path_choice[i] = 0;
        alt_pos[i] = 0;
    }

    // Initialize the remaining 300 enemies as Squares
    for (i = 400; i < NUM_ENEMIES; i++) {
        pos[i] = 0;
        hp[i] = SQUARE_HEALTH;
        dmg[i] = SQUARE_DAMAGE;
        spawn_time[i] = (i - 3) * 3; // Squares spawn every 3 time units
        time_on_map[i] = 0;
        path_choice[i] = 0;
        alt_pos[i] = 0;
    }
    initialized = true;
}
// Game state
int lives = 100;
bool game_over = false;
bool timeout_reached = false;
int global_clock = 0;

urgent broadcast chan toGoal;

// Coordinate structure
typedef struct { int x; int y; } Coord;

// Path
const int PATH_LENGTH = 23;
const Coord path[PATH_LENGTH] = {
  {0,0},{1,0},{2,0},{3,0},{4,0},{4,1},{4,2},{4,3},{4,4},{5,4},
  {6,4},{7,4},{8,4},{8,5},{8,6},{8,7},{9,7},{10,7},{11,7},{12,7},
  {13,7},{14,7},{15,4}
};

const int BRANCH_POINTS = 2;
const Coord branches[BRANCH_POINTS] = {{7,4},{10,7}};

const int ALT_PATH1_LENGTH = 10;
const Coord alt_path1[ALT_PATH1_LENGTH] = {
  {7,3},{7,2},{7,1},{8,1},{9,1},{10,1},{11,1},{12,1},{13,1},{14,1}
};

const int ALT_PATH2_LENGTH = 5;
const Coord alt_path2[ALT_PATH2_LENGTH] = {
  {10,6},{10,5},{11,5},{12,5},{13,5}
};

// Tracking path

// Main tower location
const Coord mainTower = {15, 4};

// Turret configurations for VI
const int basic_x[1] = {5};
const int basic_y[1] = {5};
const int cannon_x[4] = {8,8,14,14};
const int cannon_y[4] = {2,6,2,6};
const int sniper_x[2] = {2,11};
const int sniper_y[2] = {3,5};

// Turret configurations for VII
const int basic_x_vii[2]  = {5, 6};
const int basic_y_vii[2]  = {5, 4};
const int cannon_x_vii[1] = {8};
const int cannon_y_vii[1] = {2};
const int sniper_x_vii[1] = {11};
const int sniper_y_vii[1] = {5};

// Turret configurations for VIII
const int basic_x_viii[1]  = {5};
const int basic_y_viii[1]  = {5};
const int cannon_x_viii[2] = {8, 14};
const int cannon_y_viii[2] = {2, 2};
const int sniper_x_viii[1] = {11};
const int sniper_y_viii[1] = {5};




// Helpers


/**
 * distance(x1, y1, x2, y2):
 *   Computes Manhattan distance between the point (x1, y1)
 *   and the point (x2, y2).
 * @param x1, y1: coordinates of the first point.
 * @param x2, y2: coordinates of the second point.
 * @return abs(x1 - x2) + abs(y1 - y2).
 */
int distance(int x1, int y1, int x2, int y2) {
  return abs(x1 - x2) + abs(y1 - y2);
}



/**
 * get_enemy_position(id):
 *   Returns the current (x,y) coordinates of enemy with index id,
 *   depending on whether it is on the main path or an alternate path.
 * @param id: enemy index in [0 .. NUM_ENEMIES-1].
 * @return a Coord struct (x,y) representing that enemy’s position on the grid.
 */
Coord get_enemy_position(int id) {
  Coord dummy = {-1,-1};
  if (hp[id] <= 0) return dummy;
  if (path_choice[id]==0 && pos[id]>=0 && pos[id]<PATH_LENGTH) return path[pos[id]];
  if (path_choice[id]==1 && alt_pos[id]>=0 && alt_pos[id]<ALT_PATH1_LENGTH) return alt_path1[alt_pos[id]];
  if (path_choice[id]==2 && alt_pos[id]>=0 && alt_pos[id]<ALT_PATH2_LENGTH) return alt_path2[alt_pos[id]];
  return dummy;
}


/**
 * in_range(id, tx, ty, range):
 *   Determines if enemy[id] is within Manhattan distance ‘range’
 *   of turret located at (tx, ty).
 * @param id: index of the enemy to check.
 * @param tx, ty: turret’s (x,y) coordinates.
 * @param range: turret’s firing range (Manhattan distance).
 * @return true if distance(enemy[id].position, (tx,ty)) <= range; false otherwise.
 */
bool in_range(int id, int tx, int ty, int range) {
  Coord e = get_enemy_position(id);
  int ex = e.x, ey = e.y;
  return distance(ex, ey, tx, ty) <= range;
}

/**
 * target_available(tx, ty, range):
 *   Checks whether there is at least one alive enemy within firing range
 *   of the turret at (tx, ty). Prefers Squares over Circles on ties.
 * @param tx, ty: turret’s coordinates.
 * @param range: turret’s firing range.
 * @return true if ∃ id such that hp[id] > 0 and in_range(id, tx,ty,range); false otherwise.
 */
bool target_available(int tx, int ty, int range) {
    int i;
  for ( i = 0; i < NUM_ENEMIES; ++i)
    if (hp[i] > 0 && pos[i] >= 0 && in_range(i, tx, ty, range)) return true;
  return false;
}
//void fire(int tx, int ty, int dmg_amt, int range) {
  //  int i;
  //int target = -1;
  //for ( i = 3; i < NUM_ENEMIES; ++i)
    //if (hp[i] > 0 && in_range(i, tx, ty, range) && (target == -1 || time_on_map[i] < time_on_map[target]))
      //target = i;
  //if (target == -1)
   // for ( i = 0; i < 3; ++i)
     // if (hp[i] > 0 && in_range(i, tx, ty, range) && (target == -1 || time_on_map[i] < time_on_map[target]))
       // target = i;
  //if (target != -1) hp[target] -= dmg_amt;
//}


/**
 * fire(tx, ty, dmg_amt, range):
 *   Finds the closest alive enemy to the turret at (tx, ty)
 *   (breaking ties in favor of Squares), and subtracts ‘dmg_amt’ from its hp.
 * @param tx, ty: turret’s position.
 * @param dmg_amt: amount of damage to inflict.
 * @param range: turret’s firing range.
 * @effects Decrements hp[ chosen_enemy ] by dmg_amt if in_range.
 */

void fire(int tx, int ty, int dmg_amt, int range) {
  int i;
  int target = -1;


  for (i = 3; i < NUM_ENEMIES; ++i) {
    if (hp[i] > 0 && in_range(i, tx, ty, range)) {
      if (target == -1 ||
          time_on_map[i] < time_on_map[target] ||
          (time_on_map[i] == time_on_map[target] && i < target)) {
        target = i;
      }
    }
  }


  if (target == -1) {
    for (i = 0; i < 3; ++i) {
        if (hp[i] > 0 && in_range(i, tx, ty, range)) {
            if (target == -1 ||
            time_on_map[i] < time_on_map[target] ||
            (time_on_map[i] == time_on_map[target] && i < target)) {
          target = i;
        }
      }
    }
  }

  if (target != -1) {
    hp[target] -= dmg_amt;
  }
}

/**
 * all_enemies_gone():
 *   Checks if every enemy has either been killed or has reached the tower (i.e. removed).
 * @return true if ∀ id: (hp[id] ≤ 0) OR (enemy is marked done), false otherwise.
 */
bool all_enemies_gone() {
    int i;
  for (i = 0; i < NUM_ENEMIES; ++i) {
    if (hp[i] > 0) {
      if (path_choice[i] == 0 && pos[i] >= 0 && pos[i] < PATH_LENGTH) return false;
      if (path_choice[i] == 1 && alt_pos[i] >= 0 && alt_pos[i] < ALT_PATH1_LENGTH) return false;
      if (path_choice[i] == 2 && alt_pos[i] >= 0 && alt_pos[i] < ALT_PATH2_LENGTH) return false;
    }
  }
  return true;
}

/**
 * is_branch_point(x, y):
 *   Determines if the coordinate (x,y) matches one of the branch points
 *   on the main path (i.e., (7,4) or (10,7)).
 * @param x, y: grid coordinates to check.
 * @return true if (x,y) is one of the two branch-point coordinates; false otherwise.
 */
bool is_branch_point(int x, int y) {
    int i;
  for ( i = 0; i < BRANCH_POINTS; ++i)
    if (branches[i].x == x && branches[i].y == y) return true;
  return false;
}

/**
 * update_enemy_position(id):
 *   Advances enemy[id] one step along its chosen path (main or alternate).
 *   Updates pos[id] or alt_pos[id] depending on path_choice[id].
 * @param id: index of the enemy.
 * @effects Increments pos[id] or alt_pos[id] by 1, effectively moving the enemy.
 */
void update_enemy_position(int id) {
  if (path_choice[id] == 0) pos[id]++;
  else alt_pos[id]++;
}

/**
 * reached_path_end(id):
 *   Checks if enemy[id] has reached the last cell of its current path
 *   (main path or the chosen alternate).
 * @param id: index of the enemy.
 * @return true if pos[id] ≥ PATH_LENGTH (for main path) OR alt_pos[id] ≥ ALT_PATH?_LENGTH; false otherwise.
 */
bool reached_path_end(int id) {
  if (path_choice[id] == 0) return pos[id] >= PATH_LENGTH - 1;
  if (path_choice[id] == 1) return alt_pos[id] >= ALT_PATH1_LENGTH - 1;
  return alt_pos[id] >= ALT_PATH2_LENGTH - 1;
}

/**
 * get_enemy_speed(id):
 *   Returns the movement speed (time units per cell) for enemy[id].
 *   Circles (ids 0..2) move at speed CIRCLE_SPEED; Squares (ids ≥3) move at SQUARE_SPEED.
 * @param id: enemy index.
 * @return CIRCLE_SPEED if id < 3, else SQUARE_SPEED.
 */
int get_enemy_speed(int id) {
  return (id < 3) ? CIRCLE_SPEED : SQUARE_SPEED;
}

/**
 * is_at_branch(id):
 *   Checks if enemy[id]’s current coordinate lies on a branch point
 *   in the main path (so that it must nondeterministically choose next).
 * @param id: index of the enemy.
 * @return true if the enemy’s current (x,y) is one of the branch-point coords; false otherwise.
 */
bool is_at_branch(int id) {
  Coord p = get_enemy_position(id);
  return is_branch_point(p.x, p.y);
}

/**
 * can_move(id):
 *   Determines if enemy[id] can advance along its current path
 *   (i.e., not yet at a branch point or at path end).
 * @param id: index of the enemy.
 * @return true if not at a branch point AND not yet at path end; false otherwise.
 */
bool can_move(int id) {
  return hp[id] > 0 && !is_at_branch(id) && !reached_path_end(id);
}

/**
 * can_branch(id):
 *   Determines if enemy[id] is exactly at a branch point AND has not yet chosen a branch.
 * @param id: index of the enemy.
 * @return true if the coordinate is a branch point and path_choice[id] is still 0 (undecided); false otherwise.
 */
bool can_branch(int id) {
  return hp[id] > 0 && is_at_branch(id);
}

/**
 * mark_enemy_done(id):
 *   Cleans up enemy[id] once it has reached the tower or been killed:
 *   sets pos[id] = -1 and alt_pos[id] = -1 so it is removed from further consideration.
 * @param id: index of the enemy.
 * @effects pos[id] = -1; alt_pos[id] = -1 (marks it as “off the map”).
 */
void mark_enemy_done(int id) {
  if (path_choice[id] == 0) pos[id] = -1;
  else alt_pos[id] = -1;
}

template.declaration:
/*
EnemyTemplate(id):
- id (0..NUM_ENEMIES−1) distinguishes which enemy this automaton controls.
- When global_clock ≥ spawn_time[id], it transitions from NotActive → Spawned.
- If hp[id] ≤ 0 at any point, it goes to "Killed" (cannot be shot further).
- Otherwise, it goes to "Moving," using local clock clk to travel one cell every get_enemy_speed(id) time units.
- If it reaches a branch point (coordinates (7,4) or (10,7)), it nondeterministically picks:
    – main path (id%3==0), or
    – alt_path1 (id%3==1), or
    – alt_path2 (id%3==2).
- Once it reaches the end of its chosen path, it goes to "Goal," decrements lives by dmg[id], and leaves.
*/

clock clk;



// Calculate enemy rate as a ratio (r:q format)
// Where r is the numerator and q is the denominator
int get_enemy_speed_numerator(int enemy_id) {
    return (enemy_id < 400) ? CIRCLE_SPEED : SQUARE_SPEED;
}

int get_enemy_speed_denominator(int enemy_id) {
    return 10;
}

/*
Turret(x,y,RANGE,FIRE_RATE,DAMAGE):
    • Represents a single turret stationed at grid‐coordinate (x,y).
    • Local clock t measures time since last shot.
    • Idle → Firing when t ≥ FIRE_RATE AND target_available(x,y,RANGE) is true.
        – On that transition, reset t := 0.
    • In Firing (committed), it immediately executes fire(x,y,DAMAGE,RANGE),
      which decrements hp of the closest in‐range enemy, then returns to Idle.
    • Continues shooting as soon as t reaches FIRE_RATE again and a target remains.
*/

clock t;

// Calculate fire rate as a ratio (r:q format)
int get_fire_rate_numerator() {
    return 1;
}

int get_fire_rate_denominator() {
    return FIRE_RATE;
}

nta.system:
clock1 = ClockTick();
GM = GameMonitor();

E(const enemy_id_t id) = EnemyTemplate(id);



