Cannon2 = Turret(cannon_x[1], cannon_y[1], CANNON_RANGE, CANNON_FIRE_SPEED, CANNON_DAMAGE);
Cannon3 = Turret(cannon_x[2], cannon_y[2], CANNON_RANGE, CANNON_FIRE_SPEED, CANNON_DAMAGE);
Cannon4 = Turret(cannon_x[3], cannon_y[3], CANNON_RANGE, CANNON_FIRE_SPEED, CANNON_DAMAGE);
Sniper1 = Turret(sniper_x[0], sniper_y[0], SNIPER_RANGE, SNIPER_FIRE_SPEED, SNIPER_DAMAGE);
Sniper2 = Turret(sniper_x[1], sniper_y[1], SNIPER_RANGE, SNIPER_FIRE_SPEED, SNIPER_DAMAGE);
system clock1, GM, E, Basic1, Cannon1, Cannon2, Cannon3, Cannon4, Sniper1, Sniper2;
*/


//Turret Configurations for Configuration VII


Basic1 = Turret(basic_x_vii[0], basic_y_vii[0], BASIC_RANGE, BASIC_FIRE_SPEED, BASIC_DAMAGE);
Basic2 = Turret(basic_x_vii[1], basic_y_vii[1], BASIC_RANGE, BASIC_FIRE_SPEED, BASIC_DAMAGE);
Cannon1 = Turret(cannon_x_vii[0], cannon_y_vii[0], CANNON_RANGE, CANNON_FIRE_SPEED, CANNON_DAMAGE);
Sniper1 = Turret(sniper_x_vii[0], sniper_y_vii[0], SNIPER_RANGE, SNIPER_FIRE_SPEED, SNIPER_DAMAGE);
system clock1, GM, E, Basic1, Basic2, Cannon1, Sniper1;



